{
  "technical_and_design_decisions": [
    "Use Spring Boot security starter to provide Basic Auth functionality.",
    "Default the 'server.basic.enabled' property to false in application.yml.",
    "Use 'servers.yml' to provide single-user security configurations.",
    "Update the build configuration to pull the latest Spring Boot snapshot and release dependencies.",
    "Build Docker images using Ubuntu OS as the base, including Java 7.x and the full XD Jar.",
    "Treat U6 as a research spike, limiting the effort to assessment, documentation, and story creation."
  ],
  "assumptions": [
    "The XD Shell is an existing component that can be modified to accept new command-line arguments.",
    "The existing build system (Maven or Gradle) can easily be updated to pull the required Spring Boot versions.",
    "Standard Dockerfiles can be used to create the required sandbox and production-ready images.",
    "Redis and RabbitMQ can be easily installed and configured within the sandbox Docker image.",
    "The development environment is already set up for building and testing the Spring XD components."
  ],
  "activities": [
    {
      "activity_id": "U1",
      "activity_name": "Implement Basic Auth Option",
      "activity_description": "Add the Spring Boot security starter dependency to the spring-xd-dirt project and configure the 'server.basic.enabled' property in application.yml with a default value of false.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U2",
      "activity_name": "Implement Single-User Security Configurations",
      "activity_description": "Enable the ability to provide single-user security configurations through the 'servers.yml' file.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "U3",
      "activity_name": "Add Shell Security Credentials",
      "activity_description": "Add '--password' and '--username' options to the admin config command in the XD Shell to allow interaction with a secured xd admin server.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "U4",
      "activity_name": "Update Spring Boot Snapshot Dependency",
      "activity_description": "Update the project dependencies to pull the latest Spring Boot snapshot version.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U5",
      "activity_name": "Update Spring Boot Release Dependency",
      "activity_description": "Update the project dependencies to pull the latest Spring Boot RELEASE version.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "U6",
      "activity_name": "Spike: REST API for Archive Push",
      "activity_description": "Conduct a spike to assess customer requirements, brainstorm and document options, socialize with the team, identify phases, and create new stories for a REST API to push an archive with custom module definitions.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "U7",
      "activity_name": "Create Sandbox Docker Image",
      "activity_description": "Create a Docker image for experimentation with XD deployment, including Ubuntu OS, Full XD Jar, Java 7.x, Redis, and RabbitMQ.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "U8",
      "activity_name": "Create Production-Ready Docker Image",
      "activity_description": "Create a production-ready baseline Docker image for XD deployment, including Ubuntu OS, Full XD Jar, and Java 7.x.",
      "most_likely_effort": 4
    }
  ],
  "reported_total": {
    "most_likely_effort": 36
  }
}

